<?php
declare(strict_types=1);
require_once __DIR__.'/src/builder-commerce.php';require_once __DIR__.'/src/builder-admin.php';require_auth();header('Cache-Control: no-store');
$error='';$message='';$rows=[];$authorized=false;$page=min(100000,max(1,(int)($_GET['page']??1)));
try{
 $authorized=bc_admin();if(!$authorized){http_response_code(403);throw new RuntimeException('Acesso restrito.');}$db=bc_admin_db();
 if($_SERVER['REQUEST_METHOD']==='POST'){
  verify_csrf();$id=is_string($_POST['id']??null)?$_POST['id']:'';
  if(($_POST['action']??'')==='refund'){if(($_POST['confirm']??'')!=='yes')throw new InvalidArgumentException('Confirme a devolução integral.');br_process($db,$id);}
  elseif(($_POST['action']??'')==='sync')br_sync($db,$id);else throw new InvalidArgumentException('Ação inválida.');
  $message='Provedor consultado. Confira a situação abaixo.';
 }
 $rows=memory_sql($db,'SELECT r.*,o.customer_name,o.email,o.payment_id,o.payment_status FROM builder_refunds r JOIN builder_orders o ON o.id=r.order_id ORDER BY r.requested_at DESC LIMIT 25 OFFSET '.(($page-1)*25))->get_result()->fetch_all(MYSQLI_ASSOC);
}catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(Throwable $e){error_log('Refund admin: '.get_class($e));$error='Não foi possível concluir. Confira o provedor e a instalação de migrations/20261110_builder_refunds.sql. Não faça outra devolução sem conferir o pagamento.';}
$labels=['requested'=>'Solicitado — executar devolução','processing'=>'Enviado / aguardando confirmação','refunded'=>'Reembolso integral confirmado'];
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Reembolsos | Painel</title><link rel="stylesheet" href="css/cupons-desconto.css"><script src="js/acessibilidade-global.js?v=20261110-reviews-layout" data-accessibility-fixed defer></script></head><body class="coupons-admin"><main id="conteudo-principal"><nav><a href="home.php">← Voltar ao painel</a><a href="documentos-assinados.php">Contratos assinados</a></nav><h1>Controle de reembolsos</h1><p>Execute os pedidos tempestivos sem demora. A solicitação bloqueia os downloads; somente a confirmação do provedor indica dinheiro devolvido. Não existe recusa automática por download ou suporte.</p>
<?php if($error):?><p role="alert" class="notice"><?=sb_escape($error)?></p><?php endif;?><?php if($message):?><p role="status" class="notice"><?=sb_escape($message)?></p><?php endif;?>
<?php if($authorized):?><div class="coupon-table"><table><thead><tr><th>Pedido / cliente</th><th>Solicitação</th><th>Valor</th><th>Situação</th><th>Ações</th></tr></thead><tbody>
<?php foreach($rows as $r):?><tr><td><?=sb_escape($r['customer_name'])?><br><?=sb_escape($r['email'])?><br><code><?=sb_escape($r['order_id'])?></code><br>Pagamento: <?=sb_escape($r['payment_id'])?></td><td><?=sb_escape(bc_date($r['requested_at']))?><br>Prazo registrado: <?=sb_escape(bc_date($r['deadline_at']))?><p><?=nl2br(sb_escape($r['reason']?:'Sem motivo informado (opcional).'))?></p></td><td><?=sb_money((int)$r['amount_cents'])?><br>Inclui suporte contratado.<br>Downloads bloqueados.</td><td><?=sb_escape($labels[$r['status']]??$r['status'])?><br>Provedor: <?=sb_escape($r['payment_status'])?><br><?=sb_escape($r['provider_refund_id']??'')?><p><?=sb_escape($r['last_error']??'')?></p><small>Recibo ao cliente: <?=$r['customer_notified_at']?'enviado':'pendente'?>.<br>Confirmação final: <?=$r['completed_notified_at']?'enviada':'pendente / não concluída'?>.</small></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=sb_escape($r['order_id'])?>"><button name="action" value="sync">Conferir provedor / avisos pendentes</button></form><?php if($r['status']!=='refunded'):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=sb_escape($r['order_id'])?>"><label><input type="checkbox" name="confirm" value="yes" required>Confirmo devolver integralmente <?=sb_money((int)$r['amount_cents'])?>.</label><button name="action" value="refund">Executar reembolso integral</button></form><?php endif;?></td></tr><?php endforeach;?>
<?php if(!$rows):?><tr><td colspan="5">Nenhuma solicitação encontrada.</td></tr><?php endif;?></tbody></table></div><nav><?php if($page>1):?><a href="?page=<?=$page-1?>">Anterior</a><?php endif;?><?php if(count($rows)===25):?><a href="?page=<?=$page+1?>">Próxima</a><?php endif;?></nav><?php endif;?></main></body></html>
